               /* AuxType - not used */            integer = 0x0000;                    /* CreationDate - not used */            integer = 0x0000;                    /* CreationTime - not used */            longInt = 0x00000000;     /* SourceSize - to be filled in later */            integer = 0x0000;       /* SourcePath - null GS/OS input string */            wString;                                 /* DestPath - pathname */            byte = fieldSeparator;     /* FileSpecFiled separator character */         case DeleteOld:            key integer = Flag4+FlagD; /* FlagsWord -  Delete if older than */            integer = 0x0000;                        /* FileType - not used */            longInt = 0x00000000;                     /* AuxType - not used */            integer;       /* CreationDate - Delete if older than this date */            integer = 0x0000;                    /* CreationTime - not used */            longInt = 0x00000000;     /* SourceSize - to be filled in later */            integer = 0x0000;       /* SourcePath - null GS/OS input string */            wString;                                 /* DestPath - pathname */            byte = fieldSeparator;     /* FileSpecFiled separator character */         case Install:            key integer = Flag2;                    /* FlagsWord -  Install */            integer = 0x0000;                        /* FileType - not used */            longInt = 0x00000000;                     /* AuxType - not used */            integer = 0x0000;                    /* CreationDate - not used */            integer = 0x0000;                    /* CreationTime - not used */            longInt = 0x00000000;     /* SourceSize - to be filled in later */            wString;                               /* SourcePath - pathname */            wString;                                 /* DestPath - pathname */            byte = fieldSeparator;     /* FileSpecFiled separator character */         case Update:            key integer = Flag2+FlagU; /* FlagsWord -  Update existing file */            integer = 0x0000;                        /* FileType - not used */            longInt = 0x00000000;                     /* AuxType - not used */            integer = 0x0000;                    /* CreationDate - not used */            integer = 0x0000;                    /* CreationTime - not used */            longInt = 0x00000000;     /* SourceSize - to be filled in later */            wString;                               /* SourcePath - pathname */            wString;                                 /* DestPath - pathname */            byte = fieldSeparator;     /* FileSpecFiled separator character */      };   };   byte = fieldSeparator;            /* EndOfScript-2nd separator character */};/* ------------------------------------------------------------------------ */resource rInstallScript (1,nocrossbank) {   {/* * * * * * * *  Unconditionally delete the following old artifacts if they exist. * * * * * * * */   Delete { "BASIC.Launcher" },   Delete { "Dialog.Icons" },   Delete { "Finder.Def" },   Delete { "AppleTalk:Chooser:Chooser.0" },   Delete { "AppleTalk:Chooser:Chooser1.OVR" },   Delete { "AppleTalk:Chooser:Chooser2.OVR" },   Delete { "AppleTalk:Chooser:Chooser3.OVR" },   Delete { "AppleTalk:Chooser:Chooser4.OVR" },   Delete { "AppleTalk:Chooser:Chooser5.OVR" },   Delete { "AppleTalk:Chooser:Chooser.II" },   Delete { "AppleTalk:Chooser:IWEM" },   Delete { "AppleTalk:Chooser:MTXABS.0" },   Delete { "AppleTalk:Chooser:Finder.Data" },   Delete { "AppleTalk:Chooser" },   Delete { "AppleTalk:Namer:Namer.0" },   Delete { "AppleTalk:Namer:Namer.II" },   Delete { "AppleTalk:Namer:MtxAbs.0" },   Delete { "AppleTalk:Namer" },   Delete { "System:Launcher" },   Delete { "System:CDevs:Alphabet" },   Delete { "System:CDevs:ATIWriter" },   Delete { "System:CDevs:ATLQIWriter" },   Delete { "System:CDevs:ATLWriter" },   Delete { "Syst