k3.5 can be found and will amend the script            to "Install" their driver if appropriate.                        The Installer code will determine whether to replace System:Start            and install System:Finder based on evaluation of contents of the            System:Start file (is it the Finder?) and amend the script as is appropriate.     *//*           FULL source pathname                    Partial destination pathname w/o volume name *//*           --------------------                    ---------------------------------------------*/   Install { FirstDisk":ProDOS",                                                          "ProDOS" },   Install { FirstDisk":System:Start.GS.OS",                                  "System:Start.GS.OS" },   Install { FirstDisk":System:GS.OS",                                              "System:GS.OS" },   Install { FirstDisk":System:Error.Msg",                                      "System:Error.Msg" },   Install { FirstDisk":System:GS.OS.Dev",                                      "System:GS.OS.Dev" },   Install { FirstDisk":System:FSTs:Pro.FST",                                "System:FSTs:Pro.FST" },   Install { FirstDisk":System:FSTs:Char.FST",                              "System:FSTs:Char.FST" },   Install { FirstDisk":System:Drivers:AppleDisk3.5",                "System:Drivers:AppleDisk3.5" },   Install { FirstDisk":System:Drivers:AppleDisk5.25",              "System:Drivers:AppleDisk5.25" },   Install { FirstDisk":System:Drivers:Console.Driver",            "System:Drivers:Console.Driver" },   Update  { FirstDisk":System:Drivers:SCSIHD.Driver",              "System:Drivers:SCSIHD.Driver" },   Update  { FirstDisk":System:Drivers:SCSI.Manager",                "System:Drivers:SCSI.Manager" },   Update  { FirstDisk":System:Drivers:UniDisk3.5",                    "System:Drivers:UniDisk3.5" },   Install { FirstDisk":System:System.Setup:Tool.Setup",          "System:System.Setup:Tool.Setup" },   Ins