tem:System.Setup:EasyAccess" },   Install  { ThirdDisk":System:System.Setup:EasyMount",            "System:System.Setup:EasyMount" }, /* 24-Mar-93 SS */   Update  { ThirdDisk":System:Tools:Tool033",                              "System:Tools:Tool033" },   Update  { ThirdDisk":System:Tools:Tool038",                              "System:Tools:Tool038" },   };};#endif/* - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - *//* - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - *//* - - These equates MUST be duplicated in the Installer.Equates file!!! - - *//* - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - *//* - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - */		/* Definitions for the Custom Installation Dialog */#define Width			636#define Height			142#define Top			105-Height/2#define Left			320-Width/2#define Bottom			Top+Height#define Right			Left+Width#define ButtonLeft		273	  /* Left side of the "center" buttons		  */#define ButtonWidth		 99	  /* Width of the "center" buttons			  */#define ButtonWidth2	123	  /* Width of the wide buttons		       */#define AppWindowLeft Width-256 /* Left side of Application Selection window */#define RightMargin		  0	  /* Right margin for buttons below app window */		/* Definitions for the Standard Installation Dialog *//* NOTE:  CHANGE THESE COORDINATES, AND YOU MUST ALSO CHANGE COORDINATES IN   DiskEasyCoords & DiskBtnCoords IN DATA.ASM */#define aWidth			496#define aHeight		115#define aTop			105-aHeight/2#define aLeft			320-aWidth/2#define aBottom		aTop+aHeight#define aRight			aLeft+aWidth#define StdButtonRight	aWidth-14				/* right side of Std Update buttons */#define StdButtonLeft	StdButtonRight-156		/* left side of Std Update buttons */#define StdButtonHeight	 13		/* height of buttons *//* - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - *//* Menu related equates */#define fTitleRefIsResource	0b1000000000000000#define fMenuDisabled		0b0000000010000000#define fDontDrawTitle		0b0000000000010000	/* PopUpCtl Flags */#define fCtlProcNotPtr		0b0001000000000000	/* PopUpCtl moreFlags */#define fDrawIconInResult	0b0000000000100000#define fDrawArrowIcon		0b0000000010000000#define MenuRefIsResource     0b0000000000000010#define fCtlCanBeTarget		0b0100000000000000	/* ListCtl moreFlags */#define fCtlWantEvents		0b0010000000000000#define AppleMenuID		0x0001#define FileMenuID		0x0002#define EditMenuID		0x0003#define HelpMenuID		0x0004#define UndoItemID		0x00FA			/* These next 6 are standard and */#define CutItemID		0x00FB			/* required for DA support under */#define CopyItemID		0x00FC			/* TaskMaster.				   */#define PasteItemID		0x00FD#define ClearItemID		0x00FE#define CloseWItemID	0x00FF#define AboutItemID		0x0100			/* These are our own responsibility */#define QuitItemID		0x0101#define DividingLineID	0x0102#define ShortcutsItemID	0x0103#define EraseDiskItemID	0x0104#define HelpItemID		0x0105#define CreatingItemID	0x0106#define UpdatingItemID	0x0107#define HardDiskItemID	0x0108/* - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -  *//* Control ID's (ID - 0x300 = real control ID) for the Customized   Installation Dialog.   • • • • • • • • • •  IMPORTANT  • • • • • • • • • •   • The file "Data.Asm" provides control handle     •   • storage.  Each control, below, must have a      •   • matching 4-byte handle storage location under   •   • "HandleTable" in the same order as below!       •   • • • • • • • • • • • • • • • • • • • • • • • • • •											*/#define InstallCtl		0x0301	/* simpleButtonControl */#define RemoveCtl		0x0302#define HelpCtl		0x0303#define QuitCtl		0x0304#define DiskCtl		0x0305#define OpenCtl		0x0306#define EjectCtl		0x0307#define NewFolderCtl	0x0308#define StatText1Ctl	0x0309	/* statTextControl */#define StatText2Ctl	0x030A#define PictureCtl		0x030B	/* pictureControl */#define ScriptListCtl	0x030C	/* listControl */#define SelectListCtl	0x030D#define PopUpCtl		0x030E	/* popupControl */#define Standard2Ctl	0x030F	/* iconControl *//* Control ID's (ID - 0x300 = real control ID) for the Standard   Installation Dialog. */#define VolumeCtl		0x0401	/* simpleButtonControl */#define StandardCtl		0x0402#define CustomCtl		0x0403#define Eject2Ctl		0x0404#define Help2Ctl		0x0405#define Quit2Ctl		0x0406#define EasyTextCtl		0x0407#define EasyTextVsCtl	0x0408/* - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -  *//* ---------------------------------------------------------------------------- *//*																*//*                         Resource Type Definitions						*//*																*//* -----------------------------------------------------------------------------*/#define rIcon			0x8001#define rPicture 		0x8002#define rControlList	0x8003#define rControlTemplate	0x8004#define rPString		0x8006#define rMenuBar		0x8008#define rMenu			0x8009#define rMenuItem		0x800A#define rTextForLETextBox2 0x800B#define rCtlColorTbl	0x800D#define rWindParam1 	0x800E#define rWindColor		0x8010#define rToolStartup	0x8013#define rVersion		 $8029#define word			integer#define KeyEquiv		array[1]{ char; char; word; word; }/* - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -  */type	rToolStartup {	integer = 0x0000;				/* flags - must be set to zero		*/	integer mode320 = 0x0000,mode640 = 0x0080; /* videoMode - 640 mode		*/	integer = 0x0000;				/* resFileID - set by StartUpTools		*/	longInt = 0x00000000;			/* dPageHandle - set by StartUpTools	*/	integer = $$Countof(ToolRecs);	/* numTools - No. of tools in toolArray	*/		array ToolRecs {			integer; integer;		/* Tool number; version	*/		};};type rMenuBar {	integer = 0x0000;				/* version - must be set to zero		*/	integer = 0b1000000000000000;		/* menuFlag - resource				*/	array { longInt; };				/* menuRefArray					*/	longInt = 0x00000000;			/* end-of-array marker				*/};type rMenu {	integer = 0x0000;				/* version - must be set to zero		*/	integer;						/* menuID							*/	integer;						/* menuFlag						*/	longInt;						/* menuTitleRef					*/	  array { longInt; }; 			/* itemRefArray					*/	longInt = 0x00000000;			/* end-of-array marker				*/};type rMenuItem {	integer = 0x0000;				/* version - must be set to zero		*/	integer;						/* itemID							*/	char;						/* itemChar						*/	char;						/* itemAltChar						*/	integer = 0x0000;				/* itemCheck						*/	integer;						/* itemFlag						*/	longInt;						/* itemTitleRef					*/};type rWindParam1 {	integer	= 0x50;			/* length of parameter list, should be 0x50 */	integer;					/* p1FrameBits */	longint;					/* p1Title */	longint;					/* p1RefCon */	rect;					/* p1ZoomRect	*/	longint;					/* Color ID */	point;					/* Origin */	point;					/* data size */	point;					/* max height-width */	point;					/* scroll ver hors */	point;					/* page vers horiz */	longint;					/* p1infoRefcon */	integer;					/* p1InfoHeight */	fill long[3];				/* p1FrameDefProc,p1InfoDefProc,p1ContDefProc */	rect;					/* p1position */	longint behind=0,infront=-1;	/* p1Plane */	longint;					/* p1Storage */	integer;					/* p1InVerb */};type rWindColor {	integer;			/* frameColor */	integer;			/* titleColor */	integer;			/* tbarColor */	integer;			/* growColor */	integer;			/* infoColor */};type rControlList {		array {			longint;			};		longint = 0;};type rControlTemplate {		integer = 3+$$optionalcount (Fields);	/* pCount  (at least 6) */		longint;							/* ID     (control's ID)*/		rect;							/* rect                 */		switch {				case SimpleButtonControl:			key longint = 0x80000000;		/* procRef         */			optional Fields {				integer;					/* flags           */				integer;					/* moreFlags       */				longint;					/* refCon          */				longint;					/* titleRef        */				longint;					/* colorTableRef   */				KeyEquiv;			};		case statTextControl:			key longint = 0x81000000;		/* procRef */			optional Fields {				integer;					/* flags */				integer;					/* more flags */				longint;					/* refcon */				longint;					/* Text Ref */				integer;					/* text size */				integer;					/* text justification */			};							case CheckControl:			key longint = 0x82000000;		/* procRef         */			optional Fields {				integer;					/* flags           */				integer;					/* moreFlags       */				longint;					/* refCon          */				longint;					/* titleRef        */				integer;					/* initialValue    */				longint;					/* color table ref */				KeyEquiv;			};							case editLineControl:			key longint = 0x83000000;		/* procRef         */			optional Fields {				integer;					/* flags           */				integer;					/* moreFlags       */				longint;					/* refCon          */				integer;					/* maxSize         */				longint;					/* defaultRef        ? ? ? *//* ? ? ?			longint;					/* resource ID of the text *//* ? ? ?			integer;					/* Text Size         ? ? ? */			};												case RadioControl:				key longint = 0x84000000;	/* procRef         */			optional Fields {				integer;					/* flags           */				integer;					/* moreFlags       */				longint;					/* refCon          */				longint;					/* titleRef        */				integer;					/* initialValue    */				longint;					/* colorTableRef   */				KeyEquiv;			};			case editTextControl:			key longint = 0x85000000;		/* procRef         */			optional Fields {				integer;					/* flags           */				integer;					/* moreFlags       */				longint;					/* refCon          */				longint;					/* textFlags       */				rect;					/* indentRect      */				longint;					/* vertBar         */				integer;					/* vertAmount      */				longint;					/* horzBar         */				integer;					/* horzAmount      */				longint;					/* styleRef        */				integer;					/* textDescriptor  */				longint;					/* textRef         */				longint;					/* textLength      */				longint;					/* maxChars        */				longint;					/* maxLines        */				integer;					/* maxCharsPerLine */				integer;					/* maxHeight       */				longint;					/* colorRef        */				integer;					/* drawMode        */				LongInt;					/* filterProcPtr   */			};												case scrollControl:			key longint = 0x86000000;		/* procRef         */			optional Fields {				integer;					/* flags           */				integer;					/* moreFlags       */				longint;					/* refCon          */				integer;					/* maxSize         */				integer;					/* viewSize        */				integer;					/* initialValue    */				longint;					/* colorTableRef   */			};					case PopUpControl:			key longint = 0x87000000;		/* procRef         */			optional Fields {				integer;					/* flags           */				integer;					/* moreFlags       */				longint;					/* refCon          */				integer;					/* titleWidth      */				longint;					/* menuRef         */				integer;					/* initialValue    */				longint;					/* colorTableRef   */			};							case growControl:			key longint = 0x88000000;		/* procRef         */			optional Fields {				integer;					/* flags           */				integer;					/* moreFlags       */				longint;					/* refCon          */				longint;					/* colorTableRef   */			};		case ListControl:			key longint = 0x89000000;		/* procRef         */			optional Fields {				integer;					/* flags           */				integer;					/* moreFlags       */				longint;					/* refCon          */				integer;					/* listSize        */				integer; 					/* listView        */				integer;					/* listType        */				integer;					/* listStart       */				longint;					/* listDraw        */				integer;					/* listMemHeight   */				integer;					/* listMemSize     */				longint;					/* listRef         */				longint;					/* colorTableRef   */			};			    /* There is no 0x8A000000, 0x8B000000, 0x8C000000 */							case PictureControl:			key longint = 0x8D000000;		/* procRef         */			optional Fields {				integer;					/* flags           */				integer;					/* moreFlags       */				longint;					/* refCon          */				longint;					/* pictureRef      */			};		case IconButtonControl:			key longint = 0x07FF0001;		/* procRef         */			optional Fields {				integer;					/* flags           */				integer;					/* moreFlags       */				longint;					/* refCon          */				longint;					/* iconRef         */				longint;					/* titleRef        */				longint;					/* colorTableRef   */				integer;					/* displayMode     */				KeyEquiv;			};		};};type rCtlColorTbl {				integer;		/* outline color */				integer;		/* interior color when not hilited */				integer;		/* interior color when hilited */				integer;		/* text color when not hilited */				integer;		/* text color when not hilited */};type rPString { PString; };type rTextForLETextBox2 { string; };type rIcon {			hex integer;				/* Icon Type bit 15  1 = color, 0 = mono */	image:			integer	= (Mask-Image)/8 - 6;/* size of icon data in bytes */			integer;					/* height of icon in pixels */			integer;					/* width of icon in pixels */			hex string [$$Word(image)];	/* icon image */	mask:			hex string;					/* icon mask */};#define	Region		verUS, verFrance, verBritain, verGermany,			\					verItaly, verNetherlands, verBelgiumLux,			\					verFrBelgiumLux = 6, verSweden, verSpain,			\					verDenmark, verPortugal, verFrCanada, verNorway,	\					verIsrael, verJapan, verAustralia, verArabia,		\					verArabic=16, verFinland, verFrSwiss, verGrSwiss,	\					verGreece, verIceland, verMalta, verCyprus,			\					verTurkey, verYugoslavia, verYugoCroatian = 25,		\					verIndia = 33, verIndiaHindi = 33, verPakistan,		\					verLithuania = 41, verPoland, verHungary,			\					verEstonia, verLatvia, verLapland, verFaeroeIsl,	\					verIran, verRussia, verIreland = 50, verKorea,		\					verChina, verTaiwan, verThailand					\/*------------------- rVersion ------------------*/type rVersion {	ReverseBytes{		hex byte;											// Major revision in BCD		hex bitstring[4];									// Minor vevision in BCD		hex bitstring[4];									// Bug version		hex byte		development = 0x20,						// Release stage							alpha = 0x40,					beta = 0x60,					Final = 0x80, /* or */ 					release = 0xA0;		hex byte;											// Non-final release #	};	integer	Region;										// Region code	pstring;												// Short version number	pstring;												// Long version number};/* - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -	PictIIgs.r -- Type Declaration for RezIIgs and DeRezIIgs		Copyright Apple Computer, Inc. 1986, 1987	All rights reserved.	This Picture resource definition should probably used	for DeRez’ing purposes only.		- Change history -	12/21/88	- Mensch: created.	10/05/89	- "Jay" : a couple of minor fixes- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - */type rPicture {	integer Mode320 = 0x0000, Mode640 =0x0080;	/* SCB for picture */	Rect;								/* Bounds of picture */	Integer = 0x8211;						/* version */		array OpCodes {			switch {				case Clip:					key integer = $0001;	ClipStart:		integer = (ClipEnd[$$ArrayIndex(OpCodes)] - ClipStart[$$ArrayIndex(OpCodes)]) >> 3;					Rect;				/* region's enclosing rect */					hex string [$$Word(ClipStart[$$ArrayIndex(OpCodes)]) - 10];	ClipEnd:				case BkPat:					key integer = $0002;					hex string [32];										case TxFont:					key integer = $0003;					Longint;				/* font */										case TxFace:					key integer = $0004;					unsigned hex Integer;	/* text face */										case TxMode:					key integer = $0005;					integer		srcCopy, srcOr, srcXor, srcBic,	/* mode */								notSrcCopy, notSrcOr, notSrcXor,								notSrcBic, patCopy, patOr, patXor,								patBic, notPatCopy, notPatOr, notPatBic;										case SpExtra:					key integer = $0006;					unsigned hex longint;										case PnSize:					key integer = $0007;					Point;										case PnMode:					key integer = $0008;					unsigned hex integer;										case PnPat:					key integer = $0009;					hex string [32];										case FillPat:					key integer = $000A;					hex string [32];										case OvSize:					key integer = $000B;					Point;										case Origin:					key integer = $000C;					integer;				/* dh */					integer;				/* dv */										case TxSize:					key integer = $000D;					integer;										case FgColor:					key integer = $000E;					Integer;										case BkColor:					key integer = $000F;					Integer;										case UNUSED10:					key integer = $0010;					Point;				/* numer */					Point;				/* denom */										case Version:					key integer = $8211;				case ChExtra:					key integer = $0012;					LongInt;				case PnMask:					key integer = $0013;					hex string [8];				case ArcRot:					key integer = $0014;					integer;										case FontFlags:					key integer = $0015;					unsigned hex integer;										case AppleReserved0016:					key integer = $0016;										case AppleReserved0017:					key integer = $0017;											case AppleReserved0018:					key integer = $0018;											case AppleReserved0019:					key integer = $0019;										case AppleReserved001A:					key integer = $001A;										case Line:					key integer = $0020;					Point;					/* pnLoc */					Point;					/* newPt */											case LineFrom:					key integer = $0021;					Point;					/* newPt */										case ShortLine:					key integer = $0022;					Point;					/* pnLoc */					byte;					/* dh */					byte;					/* dv */										case ShortLineFrom:					key integer = $0023;					byte;					/* dh */					byte;					/* dv */										case AppleReserved0024:					key integer = $0024;		AR24:		unsigned integer = (AR24End - AR24) / 8 - 2;					hex string [$$Word(AR24)];		AR