vents */	  0x00000000,				/* refcon */	  NewFolderCtl,			/* title ref */	  0x00000000,				/* color table ref */	  { "N","n",0x0100,0x0100 },	/* keyEquiv */	}};};resource rControlTemplate (StatText1Ctl) {	StatText1Ctl-0x0300,		/* Application defined ID */	{ Height-43,				/* Control's bounding rectangle */	  Width-239,	  Height-34,	  Width-23 },	StatTextControl {{       $0004,					// flag: blastText	  0b0001000000000010,		/* more flags */	  0x00000000,				/* refcon */	  StatText1Ctl,			/* textRef */	  $0000,					// textLength	  $0000					// just	}};};resource rControlTemplate (StatText2Ctl) {	StatText2Ctl-0x0300,		/* Application defined ID */	{ Height-43,				/* Control's bounding rectangle */	  68,	  Height-34,	  199 },	StatTextControl {{       $0004,					// flag: blastText	  0b0001000000000010,		/* more flags */	  0x00000000,				/* refcon */	  StatText2Ctl,			/* textRef */	  $0000,					// textLength	  $0000					// just	}};};resource rControlTemplate (PictureCtl) {	PictureCtl-0x0300,			/* Application defined ID */	{ Top,Left,Bottom,Right },	/* control's bounding rectangle */	pictureControl {{	  0b1111111100000000,		/* flags */	  0b0001000000000010,		/* more flags */	  0x00000000,				/* refcon */	  PictureCtl,				/* picture ref */	}};};resource rControlTemplate (ScriptListCtl) {	ScriptListCtl-0x0300,		/* Application defined ID */	{ Height-116,5,Height-44,241 }, /* Control's bounding rectangle */	ListControl {{	  0x0000,					/* flags           */	  0b0001010000000000+fCtlCanBeTarget+fCtlWantEvents,		/* moreFlags       */	  0x00000000,				/* refCon          */	  0x0000,					/* listSize        */	  0x0007, 				/* listView        */	  0b0000000000000000,		/* listType        */	  0x0001,					/* listStart       */	  0x00000000,				/* listDraw        */	  0x000A,					/* listMemHeight   */	  0x0006,					/* listMemSize     */	  0x00000000,				/* listRef         */	  0x00000000,				/* colorTableRef   */	}};};r